using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;
using Microsoft.Agents.AI;
using OpenAI;

// --- Configuration -----------------------------------------------------------

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

Console.WriteLine($"\n🔍 Researching: {topic}\n");

// --- AI client setup ---------------------------------------------------------

IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// --- Agent setup -------------------------------------------------------------

var notebook = new Notebook();

var agent = new ChatClientAgent(chatClient, $"""
    You are a research assistant. Your goal is to thoroughly research a topic by
    searching the web multiple times to gather diverse information, taking notes on
    key findings, and finally producing a well-structured summary.

    Workflow:
    1. Break the topic into 2-3 search queries that cover different angles.
    2. For each query, call the search tool, then use the note-taking tool to
       record the most important facts, statistics, and insights.
    3. After gathering enough information, call the read_notes tool to review
       everything you collected.
    4. Produce a final comprehensive summary with sections and source references.

    Always take notes before moving to the next search. Be thorough but concise.
    """)
{
    Name = "ResearchAgent",
    Tools =
    [
        AIFunctionFactory.Create(SearchWeb),
        AIFunctionFactory.Create(notebook.TakeNote),
        AIFunctionFactory.Create(notebook.ReadNotes),
    ],
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 15,
};

// --- Run the agent -----------------------------------------------------------

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
};

Console.WriteLine("Agent is working...\n");

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n--- Research complete ---");

// --- Tools -------------------------------------------------------------------

[Description("Searches the web for information on a query. Returns a list of search result snippets.")]
static async Task<string> SearchWeb(
    [Description("The search query to look up")] string query)
{
    Console.WriteLine($"  🌐 Searching: \"{query}\"");

    using var http = new HttpClient();
    http.DefaultRequestHeaders.UserAgent.ParseAdd(
        "ResearchAgent/1.0 (educational demo)");

    try
    {
        // Use DuckDuckGo Instant Answer API (no key required)
        var encoded = Uri.EscapeDataString(query);
        var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
        var json = await http.GetStringAsync(url);
        using var doc = JsonDocument.Parse(json);
        var root = doc.RootElement;

        var results = new List<string>();

        // Abstract / main answer
        var abstractText = root.GetProperty("Abstract").GetString();
        var abstractSource = root.GetProperty("AbstractSource").GetString();
        if (!string.IsNullOrWhiteSpace(abstractText))
            results.Add($"[{abstractSource}] {abstractText}");

        // Related topics
        if (root.TryGetProperty("RelatedTopics", out var topics))
        {
            foreach (var t in topics.EnumerateArray().Take(5))
            {
                var text = t.TryGetProperty("Text", out var tv) ? tv.GetString() : null;
                if (!string.IsNullOrWhiteSpace(text))
                    results.Add(text);
            }
        }

        if (results.Count == 0)
            return $"No detailed results found for \"{query}\". Try a different query.";

        return string.Join("\n\n", results);
    }
    catch (Exception ex)
    {
        return $"Search failed: {ex.Message}. Try a different query.";
    }
}

// --- Notebook helper ---------------------------------------------------------

sealed class Notebook
{
    private readonly List<string> _notes = [];

    [Description("Saves a research note. Use this to record key facts, statistics, or insights found during research.")]
    public string TakeNote(
        [Description("A concise research note to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📝 Note #{_notes.Count} saved");
        return $"Note #{_notes.Count} saved successfully. Total notes: {_notes.Count}.";
    }

    [Description("Reads all saved research notes. Call this before writing the final summary.")]
    public string ReadNotes()
    {
        if (_notes.Count == 0)
            return "No notes have been taken yet.";

        Console.WriteLine($"  📖 Reading {_notes.Count} note(s)");
        var formatted = _notes.Select((n, i) => $"Note #{i + 1}: {n}");
        return string.Join("\n\n", formatted);
    }
}

// --- Helpers -----------------------------------------------------------------

static string PromptForTopic()
{
    Console.Write("Enter a research topic: ");
    var input = Console.ReadLine()?.Trim();
    return string.IsNullOrWhiteSpace(input)
        ? "the impact of large language models on software engineering"
        : input;
}

